#!/usr/bin/env python3
"""
Round 183o (culprits), 5 October 2026. Needs round 182b.

Underwater noise from ships and the whaling logbooks, under Oceans.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 183o (5 October)\n\nNeeds round 182b (guards on its heading). Named 183o, not 183b, because other\nchats have used the b numbers (180b to 182b are basemap rounds). Tiles patch\nround183o_tiles.py beside it. No app.js?v= bump.\n\n- Ocean harms the owner asked for, the two whose licences are open:\n  - ocean_noise: underwater noise energy ships put into the sea, each year\n    2014 to 2020, at 63, 125 and 2000 Hz (Jalkanen et al. 2022, Finnish\n    Meteorological Institute, Zenodo record 4730482, newest version, CC BY 4.0).\n    Route rasterlive, tiles ship_noise.py: each zip\'s days added up into a\n    year, eight log steps set once per pitch from the first year built (so\n    years compare), written in the key. Under Oceans > Underwater noise.\n  - whaling_logbooks: WhalingHistory.org\'s consolidated logbook data (Maury,\n    Townsend, Census of Marine Life, plus BSWF and Indian Ocean right whale\n    additions), every entry with a position, joined by voyage number to the\n    American Offshore Whaling Voyages database (columns "Voyage: ..."); CC BY\n    4.0. Route mvtlive, tiles whaling_logbooks.py, coloured by the source\'s\n    Encounter column. Under Oceans > Whaling and Meat > Marine meats > Whales.\n- Neither source could be read from the sandbox (Zenodo and whalinghistory.org\n  blocked): both scripts were tested on stand-in files shaped as the sources\n  describe. Check tiles/ocean_noise.build.json (variable, units, grid, band)\n  and whaling/build.json (files, columns, counts) after the first run.\n- Waiting on permission: seagrass trends (Dunic et al. 2021, licence "Other\n  (Open)"), Marine Sand Watch (sand@unepgrid.ch), ghost gear (GGGI data\n  sharing agreement), IWC catch records. Shark finning: FAO terms to check.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round183o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 182b" not in h.read_text(encoding="utf-8"):
        sys.exit("round183o: round 182b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round183o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round183o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round183o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
